use super::*;

macro_rules! set_lifecycle_binding_fields {
    ($binding:ident; $($field:ident = $value:expr),+ $(,)?) => {{
        $($binding.$field = $value;)+
    }};
}

pub(crate) fn bind_rollback_preview(
    binding: &mut event_log::HelloServiceLifecycleBinding,
    snapshot: Snapshot,
) {
    if let Some(probation) = snapshot.hot_swap_probation {
        set_lifecycle_binding_fields!(binding;
            rollback_preview_schema = Some(HELLO_ROLLBACK_PREVIEW_SCHEMA),
            rollback_preview_id = Some(HELLO_ROLLBACK_PREVIEW_ID),
            rollback_preview_hash = Some(hello_rollback_preview_hash(snapshot, probation)),
            rollback_preview_status = Some(HELLO_ROLLBACK_PREVIEW_STATUS),
        );
    }
}

pub(crate) fn bind_rollback_apply_denial(
    binding: &mut event_log::HelloServiceLifecycleBinding,
    snapshot: Snapshot,
) {
    set_lifecycle_binding_fields!(binding;
        rollback_apply_schema = Some(HELLO_ROLLBACK_APPLY_SCHEMA),
        rollback_apply_id = Some(HELLO_ROLLBACK_APPLY_ID),
        rollback_apply_status = Some(HELLO_ROLLBACK_APPLY_STATUS),
    );
    if let Some(probation) = snapshot.hot_swap_probation {
        let (durable_policy_write_authority_decision, recovery_inspect_source_state) =
            hello_rollback_apply_retained_denial_sources(snapshot, probation);
        let recovery_inspect_source_reference = recovery_inspect_source_state.reference;
        set_lifecycle_binding_fields!(binding;
            rollback_apply_hash = Some(hello_rollback_apply_denial_hash_with_retained_sources( snapshot, probation, Some(durable_policy_write_authority_decision), Some(recovery_inspect_source_state), )),
            rollback_apply_source_durable_policy_write_authority_decision_hash = Some(durable_policy_write_authority_decision.decision_hash),
            rollback_apply_source_recovery_rollback_inspect_source_reference_hash = recovery_inspect_source_reference.map(|reference| reference.reference_hash),
            rollback_apply_source_durable_policy_write_authority_decision_verified = durable_policy_write_authority_decision.transaction_append_dry_run_verified && durable_policy_write_authority_decision.target_region_sector_inspection_verified && durable_policy_write_authority_decision.write_authority_evidence_verified && durable_policy_write_authority_decision .audit_policy_availability_evidence_verified && durable_policy_write_authority_decision .durable_append_authority_availability_evidence_verified && durable_policy_write_authority_decision.target_span_verified,
            rollback_apply_source_recovery_rollback_inspect_source_reference_validated = recovery_inspect_source_state.ram_audit_validated,
        );
    }
}

